```json
{
  "title": "Plasmid Miniprep by Alkaline Lysis Spin Column",
  "purpose": "Isolate plasmid DNA from 1-5 mL overnight E. coli culture using alkaline lysis and silica-column purification.",
  "estimated_duration": "35-50 min",
  "biosafety": "Use non-pathogenic BSL-1 E. coli strains only. Follow local biosafety and chemical waste procedures.",
  "materials": [
    "1-5 mL overnight E. coli culture carrying plasmid",
    "Resuspension buffer with RNase A",
    "Lysis buffer",
    "Neutralization buffer",
    "Wash buffer with ethanol added",
    "Elution buffer or nuclease-free water",
    "Spin miniprep columns and collection tubes",
    "1.5 mL microcentrifuge tubes"
  ],
  "equipment": [
    "Microcentrifuge capable of 12000-16000 x g",
    "Pipettes and sterile tips",
    "Vortex mixer",
    "Timer"
  ],
  "protocol": [
    {
      "step": 1,
      "name": "Pellet cells",
      "instruction": "Transfer 1.5 mL overnight culture to a microcentrifuge tube. Centrifuge 1 min at 12000-16000 x g. Discard supernatant. Repeat with additional culture if processing more than 1.5 mL."
    },
    {
      "step": 2,
      "name": "Resuspend pellet",
      "instruction": "Add 250 uL resuspension buffer with RNase A. Resuspend completely by vortexing or pipetting until no clumps remain."
    },
    {
      "step": 3,
      "name": "Lyse cells",
      "instruction": "Add 250 uL lysis buffer. Mix gently by inverting 4-6 times. Do not vortex. Incubate at room temperature for 2-5 min."
    },
    {
      "step": 4,
      "name": "Neutralize lysate",
      "instruction": "Add 350 uL neutralization buffer. Immediately invert 6-8 times until mixture becomes cloudy. Centrifuge 10 min at 12000-16000 x g."
    },
    {
      "step": 5,
      "name": "Bind DNA",
      "instruction": "Transfer cleared supernatant to a spin column, avoiding white precipitate. Centrifuge 30-60 sec. Discard flow-through."
    },
    {
      "step": 6,
      "name": "Wash column",
      "instruction": "Add 500-750 uL wash buffer. Centrifuge 30-60 sec. Discard flow-through. Repeat if using a two-wash kit format."
    },
    {
      "step": 7,
      "name": "Dry column",
      "instruction": "Centrifuge empty column for 1-2 min to remove residual ethanol."
    },
    {
      "step": 8,
      "name": "Elute plasmid DNA",
      "instruction": "Place column in a clean tube. Add 30-50 uL elution buffer or nuclease-free water to the membrane center. Incubate 1 min, then centrifuge 1 min."
    },
    {
      "step": 9,
      "name": "QC and storage",
      "instruction": "Measure DNA concentration and purity by Nanodrop/Qubit. Store plasmid DNA at -20 C."
    }
  ],
  "expected_result": "Typical yield is 5-20 ug plasmid DNA from 1-5 mL high-copy plasmid culture, depending on strain, plasmid copy number, and culture density.",
  "notes": [
    "Avoid over-lysis, which can reduce plasmid quality.",
    "Do not transfer precipitated debris after neutralization.",
    "Residual ethanol can inhibit downstream enzymatic reactions."
  ]
}
```

